async patientVerificationByIC(data, id) {
   var name = "patientVerification";
   var pri_key = crypto.createHash("sha256").update(name).digest('hex');
   console.log("*************************************** START  ***************************************************");
   var insurance_client = new Client(pri_key);

   var today = new Date();
   var date = today.getFullYear() + '-' + (today.getMonth() + 1) + '-' + today.getDate();
   // var time = today.getHours() + ":" + today.getMinutes() + ":" + today.getSeconds();
   // var dateTime = date + ' ' + time;
   var dateTime = date;
   data["Date"] = dateTime;


   var pri_key1 = crypto.createHash("sha256").update("saveInfo").digest('hex');
   var insurance_client1 = new Client(pri_key1);
   const insurance_data1 = await insurance_client1._get_data("get");
   const validJson = insurance_data1.replace('}},', '}}');
   const ins_data = JSON.parse(validJson);
   data["clientId"] = ins_data.clientId;
   console.log(ins_data + "LLLLLLLLLLLLLLLLLLLLLLLLLLL" + ins_data.clientId);

   var pri_key2 = crypto.createHash("sha256").update("policies").digest('hex');
   var insurance_client2 = new Client(pri_key2);
   const insurance_data2 = await insurance_client2._get_data("get");
   const validreq = insurance_data2.replace('},', '}');
   const ins_policy_data = JSON.parse(validreq);
   // data["policyId"] = ins_policy_data.policyId;
   console.log(ins_policy_data.policyId + "####################Policy Data###########" + ins_policy_data);

   var newdata = {
     "resultdata": " Patient Verified Successfully",
     "Client ID": data.clientId
   };

   try {
     // Fetch and process data here
     var regdata = await insurance_client._get_data("get");
     console.log("save client data " + regdata);

     // Perform the mapping here (if necessary)
     if (regdata) {
       var cert_data = regdata;
       const validJson = cert_data.replace('},', '}');
       console.log("validjson", validJson);
       regdata = JSON.parse(validJson);
     }
     if (ins_policy_data.policyId == data.policyId) {
       if (ins_data.identityNumber == data.identityNumber) {
         if (regdata === undefined) {
           // Patient verification is successful
           insurance_client.send_data("useradd", "0", JSON.stringify(data));
           console.log("successful");
           return { "status": "Patient Verified successfully", "result": newdata };
         } else {
           // Patient verification failed because regdata is not undefined
           return { "Status": "Patient verification already done. Registration data already exists." };
         }
       } else {
         // Patient verification failed because identity numbers do not match
         return { "Status": "Patient verification failed. Identity numbers do not match." };
       }
     } else {
       // Patient verification failed because policy IDs do not match
       return { "Status": "Patient verification failed. Policy IDs do not match." };
     }
   } catch (error) {
     console.error(error);
   }
 }

